function pipeline(arr, operations) {
  let result = [...arr];
  for (const op of operations) {
    if (op.type === "filter") result = result.filter(op.fn);
    else if (op.type === "map") result = result.map(op.fn);
    else if (op.type === "sort") result = result.sort(op.fn);
  }
  return result;
}
